function handleRequest(req: Request) {
  let data;
  try {
    data = JSON.parse(req.body);
  } catch {
    data = {};
  }
  const userId = Number(data.userId) || undefined;
  saveUser({ id: userId, name: data.name || 'Guest' });
}

// Version A: boundary parser normalizes to a clean domain object
function parseOrder(req: Request): Order {
  const raw = safeJsonParse(req.body);
  return {
    id: String(raw.id || ''),
    qty: Number(raw.qty) || 0,
    note: (raw.note || '').trim()
  };
}

// Version B: pass-through parsing deferred to downstream service
function handleOrder(req: Request) {
  const body = JSON.parse(req.body);
  processOrder(body);
}
